def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses a memory‑aware approach: for moderately sized n a classic sieve;
    for very large n falls back to trial division to avoid OOM.
    """
    if n <= 2:
        return 0
    # Choose a threshold for sieve size (adjustable).
    SIEVE_LIMIT = 5_000_000
    if n <= SIEVE_LIMIT:
        limit = n - 1
        sieve = bytearray(b'\x01') * (limit + 1)
        sieve[0:2] = b'\x00\x00'
        import math
        root = int(math.isqrt(limit))
        for p in range(2, root + 1):
            if sieve[p]:
                start = p * p
                step = p
                sieve[start:limit+1:step] = b'\x00' * ((limit - start)//step + 1)
        return sum(sieve[:n])
    # Fallback trial division counting for very large n.
    import math
    count = 0
    for num in range(2, n):
        if num % 2 == 0:
            if num == 2:
                count += 1
            continue
        is_prime = True
        r = int(math.isqrt(num))
        for d in range(3, r + 1, 2):
            if num % d == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count

