def solve(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]

    def is_land(r, c):
        v = grid[r][c]
        return v == 1 or v == '1' or v == True

    def dfs(r, c):
        stack = [(r, c)]
        seen[r][c] = True
        while stack:
            x, y = stack.pop()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and not seen[nx][ny] and is_land(nx, ny):
                    seen[nx][ny] = True
                    stack.append((nx, ny))

    count = 0
    for r in range(rows):
        for c in range(cols):
            if is_land(r, c) and not seen[r][c]:
                count += 1
                dfs(r, c)
    return count

