def solve(s):
    """Check if brackets in *s* are balanced.
    Considers (), [], {}. Ignores all other characters.
    Returns True if every opening bracket has a matching closing bracket in correct order.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

